function wac_style_cpn(prefix,coupon_code){var coupon_class='coupon-'+coupon_code;if(!document.getElementsByClassName(coupon_class))return;cpn=document.getElementsByClassName(coupon_class);for(i=0;i<cpn.length;i++){if(cpn[i].innerHTML.indexOf(coupon_code)>0){txt=cpn[i].innerHTML;oprefix=txt.substring(0,txt.indexOf(': '+coupon_code)+1);oprefix=oprefix.substring(oprefix.lastIndexOf('>')+1,99);if(oprefix.length>1)cpn[i].innerHTML=cpn[i].innerHTML.replace(new RegExp(oprefix,'g'),prefix);}}}